import{_ as l,o as e,c as t,ac as o}from"./chunks/framework.Bzw8ikz_.js";const a="/hubHooks/assets/%E6%B5%8F%E8%A7%88%E5%99%A8%E6%B8%B2%E6%9F%93%E6%B5%81%E7%A8%8B.O6B0xiAC.png",u=JSON.parse('{"title":"浏览器渲染原理","description":"","frontmatter":{},"headers":[],"relativePath":"front/browser/index.md","filePath":"front/browser/index.md","lastUpdated":1773278454000}'),r={name:"front/browser/index.md"};function n(s,i,S,c,d,p){return e(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="浏览器渲染原理" tabindex="-1">浏览器渲染原理 <a class="header-anchor" href="#浏览器渲染原理" aria-label="Permalink to &quot;浏览器渲染原理&quot;">​</a></h1><p>整个渲染流程分为多个阶段，分别是： HTML 解析、样式计算、布局、分层、生成绘制指令、分块、光栅化、绘制。 整体流程如下： <img src="'+a+'" alt="image-20210724210123819" style="zoom:50%;"></p><ol><li>解析html生成dom树。在解析 HTML 的过程中，我们可以能会遇到诸如 style、link 这些标签，此时就会涉及到 CSS 的解析。 为了提高解析效率，浏览器在开始解析前，会启动一个预解析的线程，率先下载 HTML 中的外部 CSS 文件和外部的 JS 文件。 如果主线程解析到 link 位置，此时外部的 CSS 文件还没有下载解析好，主线程不会等待，继续解析后续的 HTML。这是因为下载和解析 CSS 的工作是在预解析线程中进行的。这就是 CSS 不会阻塞 HTML 解析的根本原因。最终CSS 的解析在经历了从字节数据、字符串、标记化后，最终也会形成一颗 CSSOM 树。 <em><strong>预解析线程除了下载外部 CSS 文件以外，还会下载外部 JS 文件，如果主线程解析到 script 位置，会停止解析 HTML，转而等待 JS 文件下载好，并将全局代码解析执行完成后，才能继续解析 HTML。这是因为 JS 代码的执行过程可能会修改当前的 DOM 树，所以 DOM 树的生成必须暂停。这就是 JS 会阻塞 HTML 解析的根本原因。</strong></em><blockquote><p>如果想首屏渲染的越快，就越不应该在最前面就加载 JS 文件，这也是都建议将 script 标签放在 body 标签底部的原因。 在现代浏览器中，为我们提供了新的方式来避免 JS 代码阻塞渲染的情况： async defer prefetch preload</p></blockquote></li><li>样式计算：主线程会遍历得到的 DOM 树，依次为树中的每个节点计算出它最终的样式，称之为 Computed Style。</li><li>布局：主线程会遍历刚刚构建的 DOM 树，根据 DOM 节点的计算样式计算出一个布局树（layout tree）。布局树上每个节点会有它在页面上的 x，y 坐标以及盒子大小（bounding box sizes）的具体信息。 <blockquote><p>布局树大部分时候，和 DOM 树并非一一对应。虽然它长得和先前构建的 DOM 树差不多，但是不同的是这颗树只有那些可见的（visible）节点信息。 比如 1.display:none 的节点没有几何信息，因此不会生成到布局树； 2.使用了伪元素选择器，虽然 DOM 树中不存在这些伪元素节点，但它们拥有几何信息，所以会生成到布局树中。3.还有匿名行盒、匿名块盒等等都会导致 DOM 树和布局树无法一一对应。</p></blockquote></li><li>分层：为了确定哪些元素需要放置在哪一层，主线程需要遍历整颗布局树来创建一棵层次树（Layer Tree）。分层的好处在于，将来某一个层改变后，仅会对该层进行后续处理，从而提升效率。 <blockquote><p>能够导致浏览器为其创建新的渲染层的，包括以下几类常见的情况：</p><ul><li>根元素 document;</li><li>有明确的定位属性（relative、fixed、sticky、absolute）;</li><li>opacity &lt; 1;</li><li>有 CSS fliter 属性;</li><li>有 CSS mask 属性;</li><li>有 CSS mix-blend-mode 属性且值不为 normal;</li><li>有 CSS transform 属性且值不为 none;</li><li>backface-visibility 属性为 hidden;</li><li>有 CSS reflection 属性;</li><li>有 CSS column-count 属性且值不为 auto或者有 CSS column-width 属性且值不为 auto;</li><li>当前有对于 opacity、transform、fliter、backdrop-filter 应用动画;</li><li>overflow 不为 visible;</li></ul></blockquote></li><li>生成绘制指令: 主线程会为每个层单独产生绘制指令集，用于描述这一层的内容该如何画出来。生成绘制指令集后，还没有开始执行这些指令,但渲染主线程的工程就暂时告一段落，接下来主线程将每个图层的绘制信息提交给合成线程，剩余工作将由合成线程完成。</li><li>分块：合成线程首先对每个图层进行分块，将其划分为更多的小区域。多线程进行</li><li>光栅化：光栅化的操作，并不由合成线程来做，而是会由合成线程将块信息交给 GPU 进程，以极高的速度完成光栅化。在这个阶段，渲染树中每个节点的计算布局信息被转换为屏幕上的实际像素。</li><li>绘制（paint）：遍历渲染树，调用渲染器的 paint() 方法在屏幕上绘制出节点内容，本质上是一个像素填充的过程。这个过程也出现于回流或一些不影响布局的 CSS 修改引起的屏幕局部重画，这时候它被称为重绘（Repaint）。</li></ol>',3)])])}const f=l(r,[["render",n]]);export{u as __pageData,f as default};
